// Pure helpers of thimble-cc-mod (no `$`), shared by the hooks module, the surface modules and the tests.
//
// - citations(text): the [[display|ref]] and [[ref]] citations of a reply, and the link form [display](ref).
// - parseReply(text): a reply block cut into Markdown chunks, card embeds (a line holding only [[card:<id>]]) and rich
//   blocks (a paragraph, list item, heading, quote or table that holds a citation), each rich block as inline runs.
// - shownMatches / valueIn: thimble's number comparison (backend/app/cite.py), for the verification script's result.

export type Citation = { raw: string; ref: string; display: string | null }

export type Run = { text: string; b?: boolean; i?: boolean; code?: boolean; u?: boolean; cite?: Citation }

/** `gap`: a blank line stood before the block in the reply, so it is drawn one row below the one before it. */
export type Block =
  | { type: 'md'; text: string; gap: boolean }
  | { type: 'card'; id: string; gap: boolean }
  | { type: 'rich'; prefix: string; heading: number; quote: boolean; runs: Run[]; gap: boolean; table?: TableRuns }

/** A Markdown table that holds citations, drawn by thimble-cc-mod (the `|` inside `[[value|ref]]` breaks a GFM table):
 *  its rows of cells of runs, the first row the header, and each column's alignment. A table block's `runs` are its
 *  cells' runs in reading order, so its chips are numbered as a paragraph's are. */
export type TableRuns = { rows: Run[][][]; align: ('left' | 'right' | 'center')[] }

const SPAN_RE = /\[\[([^\[\]]+?)\]\]/g
const FENCE_RE = /```[\s\S]*?```|`[^`\n]*`/g
const LINK_RE = /(?<![\[!])\[([^\[\]\n]*)\]\(\s*(?:<([^<>\n]+)>|((?:[^()\s<>]|\([^()\s]*\))+))\s*\)/g
const WEB_RE = /^(?:[a-z][a-z0-9+.-]*:\/\/|mailto:|tel:)/i
const REF_SHAPE = /^(?:call:[A-Za-z0-9_-]+(?:#L\d+(?:-L?\d+)?)?|card:[A-Za-z0-9_-]+(?:#.*)?|[^\s:#]+#\S+|[^\s:#()]+\.[A-Za-z][A-Za-z0-9]{0,7})$/
export const EMBED_RE = /^\s*(?:\[\[card:([A-Za-z0-9_-]+)\]\]|!\[[^\]\n]*\]\(card:([A-Za-z0-9_-]+)\))\s*$/

function make(display: string | null, ref: string): Citation {
  return { raw: display === null ? `[[${ref}]]` : `[[${display}|${ref}]]`, ref, display }
}

function spanCitation(inner: string): Citation | null {
  const t = inner.trim()
  const bar = t.indexOf('|')
  const display = bar >= 0 ? t.slice(0, bar).trim() : null
  const ref = (bar >= 0 ? t.slice(bar + 1) : t).trim()
  return ref ? make(display, ref) : null
}

function linkCitation(shown: string, target: string): Citation | null {
  const ref = target.trim().replaceAll('%20', ' ')
  if (!ref || WEB_RE.test(ref) || shown.includes('|') || !REF_SHAPE.test(ref)) return null
  const s = shown.trim()
  return make(s === '' || s === '↗' ? null : s, ref)
}

/** Every citation of a text in order, deduplicated by its `[[...]]` spelling; code spans and fences left out. */
export function citations(text: string): Citation[] {
  const found: { at: number; c: Citation }[] = []
  const clean = text.replace(FENCE_RE, m => ' '.repeat(m.length))
  for (const m of clean.matchAll(SPAN_RE)) {
    const c = spanCitation(m[1]!)
    if (c) found.push({ at: m.index ?? 0, c })
  }
  for (const m of clean.matchAll(LINK_RE)) {
    const c = linkCitation(m[1]!, m[2] ?? m[3] ?? '')
    if (c) found.push({ at: m.index ?? 0, c })
  }
  const seen = new Set<string>()
  return found
    .sort((a, b) => a.at - b.at)
    .map(f => f.c)
    .filter(c => !seen.has(c.raw) && Boolean(seen.add(c.raw)))
}

/** A short stable id for a citation (FNV-1a of its raw spelling), the key of its state. */
export function cid(raw: string): string {
  let h = 0x811c9dc5
  for (let i = 0; i < raw.length; i++) {
    h ^= raw.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h.toString(36)
}

/** What a chip says: the shown value, or a short name of the place for a citation without one. */
export function chipLabel(c: Citation): string {
  if (c.display !== null) return c.display.length > 40 ? `${c.display.slice(0, 39)}…` : c.display
  const [base = '', frag = ''] = c.ref.split('#', 2)
  if (base.startsWith('card:')) return frag ? `card ${frag.split('/').at(-1)}` : 'card'
  if (base.startsWith('call:')) return frag ? `output ${frag}` : 'output'
  const name = base.split('/').at(-1) ?? base
  const short = name.replace(/\.(jsonl|json|csv|tsv|txt|md|log)$/, '')
  const where = frag.startsWith('L') ? `:${frag.slice(1).replace('-L', '-')}` : frag ? `#${frag}` : ''
  const label = `${short}${where}`
  return label.length > 24 ? `${label.slice(0, 23)}…` : label
}

// ---------------------------------------------------------------------------------------- inline runs

/** A line of Markdown as styled runs: bold, italic, code, links (their text), citations (one run each). */
export function inlineRuns(text: string): Run[] {
  const out: Run[] = []
  // tokens: code span, citation, link (citation form or web), bold, italic
  const TOKEN = /(`[^`\n]+`)|(\[\[[^\[\]]+?\]\])|((?<![\[!])\[[^\[\]\n]*\]\([^()\s]*(?:\([^()\s]*\)[^()\s]*)*\))|(\*\*[^*\n]+\*\*|__[^_\n]+__)|((?<![\w*])\*[^*\n]+\*(?!\w)|(?<![\w_])_[^_\n]+_(?![\w]))/g
  let last = 0
  const push = (r: Run) => {
    if (r.text) out.push(r)
  }
  for (const m of text.matchAll(TOKEN)) {
    const at = m.index ?? 0
    push({ text: text.slice(last, at) })
    const tok = m[0]
    if (m[1]) push({ text: tok.slice(1, -1), code: true })
    else if (m[2]) {
      const c = spanCitation(tok.slice(2, -2))
      if (c) out.push({ text: chipLabel(c), cite: c })
      else push({ text: tok })
    } else if (m[3]) {
      const lm = /^\[([^\[\]\n]*)\]\((.*)\)$/.exec(tok)
      const c = lm ? linkCitation(lm[1]!, lm[2]!) : null
      if (c) out.push({ text: chipLabel(c), cite: c })
      else push({ text: lm ? lm[1]! : tok, u: true })
    } else if (m[4]) {
      for (const r of inlineRuns(tok.slice(2, -2))) push({ ...r, b: true })
    } else if (m[5]) {
      for (const r of inlineRuns(tok.slice(1, -1))) push({ ...r, i: true })
    }
    last = at + tok.length
  }
  push({ text: text.slice(last) })
  return out
}

// ---------------------------------------------------------------------------------------- blocks

/** A table row's cells: split at each bar outside citations and code spans; an escaped bar stays in its cell. */
export function tableCells(line: string): string[] {
  let t = line.trim()
  if (t.startsWith('|')) t = t.slice(1)
  if (t.endsWith('|') && !t.endsWith('\\|')) t = t.slice(0, -1)
  const cells: string[] = []
  let cur = ''
  let depth = 0
  let code = false
  for (let i = 0; i < t.length; i++) {
    const ch = t[i]!
    if (ch === '\\' && t[i + 1] === '|') {
      cur += '|'
      i++
      continue
    }
    if (!code && t.startsWith('[[', i)) depth++
    else if (!code && depth > 0 && t.startsWith(']]', i)) depth--
    if (ch === '`') code = !code
    if (ch === '|' && depth === 0 && !code) {
      cells.push(cur.trim())
      cur = ''
      continue
    }
    cur += ch
  }
  cells.push(cur.trim())
  return cells
}

const ALIGN_ROW = /^\s*\|?\s*:?-+:?\s*(\|\s*:?-+:?\s*)*\|?\s*$/

/** A Markdown table's lines as rows of runs, the alignment row read and left out. */
export function tableRuns(lines: string[]): TableRuns {
  const rows: Run[][][] = []
  let align: TableRuns['align'] = []
  for (const line of lines) {
    if (ALIGN_ROW.test(line) && line.includes('-')) {
      align = tableCells(line).map(c => (c.startsWith(':') && c.endsWith(':') ? 'center' : c.endsWith(':') ? 'right' : 'left'))
      continue
    }
    rows.push(tableCells(line).map(c => inlineRuns(c)))
  }
  return { rows, align }
}

/** A reply block cut into what the engine draws as Markdown (no citation in it), the cards it embeds, and the rich
 *  blocks thimble-cc-mod draws itself so their citations can be chips. Fences and tables stay Markdown whole. */
export function parseReply(text: string): Block[] {
  const lines = text.split('\n')
  const out: Block[] = []
  let md: string[] = []
  let blank = false // the line before the next block was blank
  const flush = () => {
    const first = md.findIndex(l => l.trim() !== '')
    if (first >= 0) {
      let last = md.length - 1
      while (!md[last]!.trim()) last--
      out.push({ type: 'md', text: md.slice(first, last + 1).join('\n'), gap: blank || first > 0 })
      blank = last < md.length - 1
    } else if (md.length) blank = true
    md = []
  }
  let i = 0
  while (i < lines.length) {
    const line = lines[i]!
    const embed = EMBED_RE.exec(line)
    if (embed) {
      flush()
      out.push({ type: 'card', id: (embed[1] ?? embed[2])!, gap: blank })
      blank = false
      i++
      continue
    }
    if (/^\s*```/.test(line)) {
      const start = i
      i++
      while (i < lines.length && !/^\s*```/.test(lines[i]!)) i++
      md.push(...lines.slice(start, Math.min(i + 1, lines.length)))
      i++
      continue
    }
    if (/^\s*\|/.test(line)) {
      const start = i
      while (i < lines.length && /^\s*\|/.test(lines[i]!)) i++
      const rows = lines.slice(start, i)
      if (citations(rows.join('\n')).length === 0) {
        md.push(...rows)
        continue
      }
      flush()
      const table = tableRuns(rows)
      out.push({ type: 'rich', prefix: '', heading: 0, quote: false, runs: table.rows.flat(2), gap: blank, table })
      blank = false
      continue
    }
    if (!line.trim()) {
      md.push(line)
      i++
      continue
    }
    // one block: a heading, a list item (with its continuation lines), a quote, or a paragraph
    const head = /^(#{1,6})\s+(.*)$/.exec(line)
    const item = /^(\s*)([-*+]|\d+[.)])\s+(.*)$/.exec(line)
    const quote = /^\s*>\s?(.*)$/.exec(line)
    const start = i
    let body: string[]
    let prefix = ''
    let heading = 0
    let isQuote = false
    if (head) {
      heading = head[1]!.length
      body = [head[2]!]
      i++
    } else if (item) {
      prefix = `${item[1]!.replace(/\t/g, '  ')}${item[2]!} `
      body = [item[3]!]
      i++
      while (i < lines.length && lines[i]!.trim() && /^\s{2,}\S/.test(lines[i]!) && !/^\s*([-*+]|\d+[.)])\s/.test(lines[i]!)) body.push(lines[i++]!.trim())
    } else if (quote) {
      isQuote = true
      body = []
      while (i < lines.length && /^\s*>/.test(lines[i]!)) body.push(lines[i++]!.replace(/^\s*>\s?/, ''))
    } else {
      body = []
      while (
        i < lines.length && lines[i]!.trim() && !EMBED_RE.test(lines[i]!) && !/^\s*(```|\||#{1,6}\s|>|([-*+]|\d+[.)])\s)/.test(lines[i]!)
      ) body.push(lines[i++]!)
    }
    const joined = body.join(' ')
    if (citations(joined).length === 0) {
      md.push(...lines.slice(start, i))
      continue
    }
    flush()
    out.push({ type: 'rich', prefix, heading, quote: isQuote, runs: inlineRuns(joined), gap: blank })
    blank = false
  }
  flush()
  if (out[0]) out[0].gap = false
  return out
}

/** A chunk of Markdown cut into its paragraphs (at blank lines outside a fence), each whole: what one "ask ›" asks
 *  about. A fence, a table or a list stays one piece. */
export function mdPieces(text: string): string[] {
  const out: string[] = []
  let cur: string[] = []
  let fence = false
  for (const line of text.split('\n')) {
    if (/^\s*```/.test(line)) fence = !fence
    if (!fence && !line.trim()) {
      if (cur.length) out.push(cur.join('\n'))
      cur = []
    } else cur.push(line)
  }
  if (cur.length) out.push(cur.join('\n'))
  return out
}

/** Each heading of a reply text and its section: the heading, and every line up to the next heading of its level or
 *  higher (its paragraphs, lists, tables and cards), keyed by the heading line as written. What "ask ›" beside a
 *  heading asks about. Headings inside a fence are not headings. */
export function sectionsOf(text: string): Map<string, string> {
  const lines = text.split('\n')
  const heads: { at: number; level: number }[] = []
  let fence = false
  lines.forEach((l, i) => {
    if (/^\s*```/.test(l)) fence = !fence
    const m = fence ? null : /^(#{1,6})\s+\S/.exec(l)
    if (m) heads.push({ at: i, level: m[1]!.length })
  })
  const out = new Map<string, string>()
  heads.forEach((h, k) => {
    const end = heads.slice(k + 1).find(x => x.level <= h.level)?.at ?? lines.length
    out.set(lines[h.at]!.trim(), lines.slice(h.at, end).join('\n').trim())
  })
  return out
}

/** Whether a reply block needs thimble-cc-mod's drawing: it embeds a card or holds a citation. */
export function needsDrawing(text: string): boolean {
  return text.split('\n').some(l => EMBED_RE.test(l)) || citations(text).length > 0
}

// ---------------------------------------------------------------------------------------- numbers (cite.py port)

const NUM_RE = /(?<![\w:./#\-−])[-−]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?%?(?![\w%:])/g
const PLAIN_RE = /^[-−]?(?:(?:0|[1-9][0-9]*)(?:\.[0-9]*)?|\.[0-9]+)$/
const QUOTES = '"\'“”‘’'

type Num = { v: bigint; scale: number }

function parts(s: string): Num | null {
  const t = s.trim().replaceAll(',', '').replaceAll('−', '-').replace(/%+$/, '').trim()
  if (!PLAIN_RE.test(t)) return null
  const neg = t.startsWith('-')
  const body = neg ? t.slice(1) : t
  const [int = '', frac = ''] = body.split('.')
  const v = BigInt((int || '0') + frac)
  return { v: neg ? -v : v, scale: frac.length }
}

function scaled(n: Num, scale: number): bigint {
  return n.v * 10n ** BigInt(scale - n.scale)
}

function eq(a: Num, b: Num): boolean {
  const s = Math.max(a.scale, b.scale)
  return scaled(a, s) === scaled(b, s)
}

function rounded(b: Num, d: number): Num[] {
  if (d >= b.scale) return [b]
  const div = 10n ** BigInt(b.scale - d)
  const neg = b.v < 0n
  const mag = neg ? -b.v : b.v
  const q = mag / div
  const r = mag % div
  const up = r * 2n >= div ? q + 1n : q
  const even = r * 2n > div || (r * 2n === div && q % 2n === 1n) ? q + 1n : q
  const sign = (x: bigint) => (neg ? -x : x)
  return [{ v: sign(up), scale: d }, { v: sign(even), scale: d }]
}

function norm(tok: string): string {
  const s = tok.replaceAll(',', '').replaceAll('−', '-').replace(/%+$/, '').trim()
  const n = parts(s)
  if (!n) return s
  let { v, scale } = n
  while (scale > 0 && v % 10n === 0n) {
    v /= 10n
    scale -= 1
  }
  if (v === 0n) return '0'
  const neg = v < 0n
  const digits = (neg ? -v : v).toString().padStart(scale + 1, '0')
  const text = scale ? `${digits.slice(0, -scale)}.${digits.slice(-scale)}` : digits
  return neg ? `-${text}` : text
}

/** The same value, or `shown` with only decimals dropped by rounding: "91%" cites 91.2, "6,500" does not cite 6,543. */
export function shownMatches(token: string, shown: string): boolean {
  const a = parts(token)
  const b = parts(shown)
  if (!a || !b) return norm(token) !== '' && norm(token) === norm(shown)
  if (eq(a, b)) return true
  return a.scale < b.scale && rounded(b, a.scale).some(r => eq(a, r))
}

/** Whether a shown value is in a text: a number must match a whole number of it, anything else is a substring. */
export function valueIn(display: string, text: string): boolean {
  for (const m of text.matchAll(NUM_RE)) if (shownMatches(display, m[0])) return true
  const d = display.trim()
  if (new RegExp(`^(?:${NUM_RE.source})$`).test(d)) return false
  let words = d
  if (words.length > 2 && QUOTES.includes(words[0]!) && QUOTES.includes(words.at(-1)!)) words = words.slice(1, -1)
  return text.replaceAll(',', '').includes(norm(words))
}

/** The value a verification script printed: its last line of the form `RESULT: <value>`, or null. */
export function scriptResult(stdout: string): string | null {
  const hits = [...stdout.matchAll(/^RESULT:\s*(.+?)\s*$/gm)]
  return hits.length ? hits.at(-1)![1]! : null
}

/** A value as a card shows it: an integer whole, a float to at most 3 decimals. */
export function fmt(v: unknown): string {
  if (typeof v === 'number') {
    if (!Number.isFinite(v)) return String(v)
    if (Number.isInteger(v)) return String(v)
    const s = v.toFixed(3).replace(/0+$/, '').replace(/\.$/, '')
    return s === '-0' ? '0' : s
  }
  return v === null || v === undefined ? '' : String(v)
}

export function clip(s: string, n: number): string {
  const one = s.replace(/\s+/g, ' ').trim()
  return one.length > n ? `${one.slice(0, Math.max(0, n - 1))}…` : one
}

/** The sentence of a reply that holds a citation, for the prompt that asks for its verification script. */
export function sentenceOf(text: string, raw: string): string {
  const at = text.indexOf(raw)
  if (at < 0) return ''
  const before = text.slice(0, at)
  const start = Math.max(before.lastIndexOf('. ') + 1, before.lastIndexOf('\n') + 1, 0)
  const rest = text.slice(at)
  const m = /[.!?](\s|$)|\n/.exec(rest)
  return text.slice(start, at + (m ? m.index + 1 : rest.length)).trim()
}

// ---------------------------------------------------------------------------------------- card files

export const CARD_KINDS = ['bar', 'line', 'timeline', 'table', 'example', 'diagram'] as const
export const MAX_DIAGRAM_NODES = 40
export const MAX_DIAGRAM_EDGES = 80

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)
const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v)
const isStr = (v: unknown): v is string => typeof v === 'string'
const isCell = (v: unknown) => v === null || isStr(v) || isNum(v) || typeof v === 'boolean'

/** Why a card file cannot be drawn, or null when it fits its kind's spec. The mod draws only these six typed specs;
 *  a card that fails is drawn as this error, and main is asked to fix it. */
export function validateCard(c: unknown, id?: string): string | null {
  if (!isObj(c)) return 'the file is not a JSON object'
  if (!isStr(c.id) || !/^[A-Za-z0-9_-]+$/.test(c.id)) return 'no valid id'
  if (id !== undefined && c.id !== id) return `its id is ${c.id}, not ${id}`
  if (!isStr(c.kind) || !(CARD_KINDS as readonly string[]).includes(c.kind)) return `kind must be one of ${CARD_KINDS.join(', ')}`
  if (!isStr(c.question) || !c.question.trim()) return 'no question'
  const list = (k: string) => (Array.isArray(c[k]) ? (c[k] as unknown[]) : null)
  switch (c.kind) {
    case 'bar': {
      const rows = list('rows')
      if (!rows?.length) return 'a bar card needs rows'
      const bad = rows.findIndex(r => !isObj(r) || !isStr(r.label) || !isNum(r.value))
      if (bad >= 0) return `bar row ${bad + 1} needs a label and a finite number value`
      break
    }
    case 'line': {
      const series = list('series')
      if (!series?.length) return 'a line card needs series'
      for (const s of series) {
        if (!isObj(s) || !isStr(s.name) || !Array.isArray(s.points) || s.points.length === 0) return 'each series needs a name and points'
        const bad = (s.points as unknown[]).findIndex(p => !Array.isArray(p) || p.length !== 2 || !(isStr(p[0]) || isNum(p[0])) || !isNum(p[1]))
        if (bad >= 0) return `series ${s.name}: point ${bad + 1} must be [x, number]`
      }
      break
    }
    case 'timeline': {
      const evs = list('events')
      if (!evs?.length) return 'a timeline card needs events'
      const bad = evs.findIndex(e => !isObj(e) || !isStr(e.time) || !isStr(e.label) || !isStr(e.ref) || !(e.shown === undefined || isStr(e.shown)))
      if (bad >= 0) return `event ${bad + 1} needs time, label and ref (shown is optional text)`
      break
    }
    case 'table': {
      const cols = list('columns')
      const rows = list('rows')
      if (!cols?.length || !cols.every(isStr)) return 'a table card needs columns, as strings'
      if (!rows) return 'a table card needs rows'
      const bad = rows.findIndex(r => !Array.isArray(r) || r.length !== cols.length || !r.every(isCell))
      if (bad >= 0) return `table row ${bad + 1} must have ${cols.length} plain values`
      break
    }
    case 'example': {
      const exs = list('examples')
      if (!exs?.length) return 'an example card needs examples'
      const bad = exs.findIndex(e => !isObj(e) || !isStr(e.ref) || !/#L\d+/.test(e.ref) || !isStr(e.quote))
      if (bad >= 0) return `example ${bad + 1} needs a ref to lines (file#L12) and a quote`
      break
    }
    case 'diagram': {
      const nodes = list('nodes')
      const edges = list('edges') ?? []
      if (!nodes?.length) return 'a diagram card needs nodes'
      if (nodes.length > MAX_DIAGRAM_NODES) return `a diagram card shows at most ${MAX_DIAGRAM_NODES} nodes`
      if (edges.length > MAX_DIAGRAM_EDGES) return `a diagram card shows at most ${MAX_DIAGRAM_EDGES} edges`
      const opt = (v: unknown) => v === undefined || isStr(v)
      const bad = nodes.findIndex(n => !isObj(n) || !isStr(n.id) || !n.id || !isStr(n.label) || !n.label.trim() || !opt(n.ref) || !opt(n.detail))
      if (bad >= 0) return `node ${bad + 1} needs an id and a label (ref and detail are optional text)`
      const ids = new Set(nodes.map(n => (n as { id: string }).id))
      if (ids.size !== nodes.length) return 'each node needs an id of its own'
      const badE = edges.findIndex(e => !isObj(e) || !isStr(e.source) || !isStr(e.target) || !ids.has(e.source) || !ids.has(e.target) || !opt(e.label))
      if (badE >= 0) return `edge ${badE + 1} needs a source and a target among the node ids`
      break
    }
  }
  if (c.params !== undefined) {
    if (!Array.isArray(c.params)) return 'params must be a list'
    for (const p of c.params as unknown[]) {
      if (!isObj(p) || !isStr(p.name) || !Array.isArray(p.choices) || !p.choices.some(x => String(x) === String(p.value))) {
        return 'each param needs a name, choices and a value among them'
      }
    }
  }
  return null
}

/** The ids of the cards a reply embeds (lines holding only [[card:<id>]]), in order. */
export function embeddedCards(text: string): string[] {
  const out: string[] = []
  for (const line of text.split('\n')) {
    const m = EMBED_RE.exec(line)
    if (m) out.push((m[1] ?? m[2])!)
  }
  return out
}

/** The paragraph after a card's embed line: the card's takeaway, as the reply wrote it. */
export function takeawayAfter(text: string, id: string): string {
  const lines = text.split('\n')
  const at = lines.findIndex(l => {
    const m = EMBED_RE.exec(l)
    return m !== null && (m[1] ?? m[2]) === id
  })
  if (at < 0) return ''
  let i = at + 1
  while (i < lines.length && !lines[i]!.trim()) i++
  const out: string[] = []
  while (i < lines.length && lines[i]!.trim() && !EMBED_RE.test(lines[i]!) && !/^\s*(#{1,6}\s|```|\|)/.test(lines[i]!)) out.push(lines[i++]!)
  return out.join('\n')
}

/** A one-line version of a side thread's answer to offer main: its `FOR MAIN:` line, else its first sentence. */
export function forMain(answer: string): string {
  const m = /^\s*FOR MAIN:\s*(.+)$/m.exec(answer)
  if (m) return m[1]!.trim()
  const first = answer.replace(/\s+/g, ' ').trim()
  const end = /[.!?](\s|$)/.exec(first)
  return end ? first.slice(0, end.index + 1) : first.slice(0, 200)
}

/** A prompt as thimble-cc-mod sent it, without the engine's framing around a plugin's prompt ("The thimble-cc-mod plugin
 *  sent a message:" before it, a line on how plugin prompts are surfaced after it); other prompts unchanged. */
export function unframed(text: string): string {
  return text
    .replace(/^\s*The thimble-cc-mod plugin sent a message:\s*/, '')
    .replace(/\n+This is how Claude Code surfaces a prompt a plugin submits[\s\S]*$/, '')
    .trim()
}

/** Whether a prompt is one thimble-cc-mod sent main (a fix request, a verification request, a note). */
export function fromMod(text: string): boolean {
  return unframed(text).startsWith('thimble-cc-mod')
}

/** A side thread's answer as the pane draws it: its `FOR MAIN:` line left out (the pane offers it as a button). */
export function threadBody(answer: string): string {
  return answer.replace(/^\s*FOR MAIN:.*$/m, '').trim()
}

files.hooks/paint.ts:
// Colours, and styled lines to elements, for a Client's table or a render hook's: one Text per line, one nested Text per
// segment.
//
// A colour is a key of Claude Code's theme where one fits, so text, links, problems and highlights follow the theme the
// analyst picked (light, dark, daltonized, ANSI). Chart series have no theme key, so they are mid-luminance colours that
// keep 3:1 contrast on light and on dark backgrounds (tests/cards.test.ts checks both).
import type { BoxProps, ElementConstructor, RenderElement, TextProps } from 'claude-code'

import type { Line, Seg } from './draw'

type TextC = ElementConstructor<TextProps>
type BoxC = ElementConstructor<BoxProps>

export const SERIES = ['#2f7de1', '#c2710c', '#1f9d55', '#9061f9', '#0f9a8f', '#e0457b'] as const

export const COLORS = {
  series: [...SERIES] as string[],
  negative: '#e5484d',
  /** a mark under the pointer, and the readout of its value */
  accent: 'text',
  text: 'text',
  dim: 'inactive',
  /** borders, axes and rules */
  rule: 'subtle',
  /** the background of the row or column under the pointer */
  cursor: 'userMessageBackground',
  /** the background of a cited value in the lines a citation panel shows */
  highlight: 'selectionBg',
  /** the background of the open menu's target (a passage, a card's title, a mark), clear on light and dark themes */
  menu: 'selectionBg',
  code: 'permission',
  link: 'remember',
  problem: 'error',
  ok: 'success',
  warn: 'warning',
}

function seg(Text: TextC, s: Seg): RenderElement {
  const p: TextProps = {}
  if (s.fg) p.color = s.fg
  if (s.bg) p.backgroundColor = s.bg
  if (s.b) p.bold = true
  if (s.d) p.dimColor = true
  if (s.i) p.italic = true
  if (s.u) p.underline = true
  if (s.inv) p.inverse = true
  return Text({ ...p, children: s.s })
}

export function paintLine(Text: TextC, l: Line): RenderElement {
  return Text({ wrap: 'truncate-end', children: l.length ? l.map(s => seg(Text, s)) : ' ' })
}

export function paintLines(Box: BoxC, Text: TextC, lines: Line[]): RenderElement {
  return Box({ flexDirection: 'column', children: lines.map(l => paintLine(Text, l)) })
}

files.hooks/gestures.tsx:
// One set of gestures for every target a Client of the mod draws (a card, a mark, a row, a record, a node):
//
//   click            the target's one action: open the place it cites, or a side thread about a card
//   double-click     the same as a click
//   right-click      a menu of every action
//
// Modifier clicks and the middle button are left alone: terminals keep them for their own selection, and a gesture
// that works in one terminal and not the next is worse than none. A reply's paragraphs are the engine's Markdown, each
// citation a link a plain click presses (register.tsx), so their text selects as usual.
//
// A Client calls onPointer from its pointer listener with the target under the pointer; the gesture is posted to the
// hooks module (register.tsx), which acts on it.
import type { ClientModule, ClientPointerEvent, JsonValue } from 'claude-code'

import type { ChatTarget } from '../types'
import { citeLabel, sentenceAt } from './cite'
import type { ParaLayout } from './cite'
import { lineWidth, shade } from './draw'
import type { Line } from './draw'
import { citations } from './lib'
import type { Citation } from './lib'
import { COLORS } from './paint'

export type Target = ChatTarget

export type PointerEv = { button: 'left' | 'middle' | 'right'; shift: boolean; ctrl: boolean; alt: boolean; type: 'press' | 'release' | 'double' }

export type Gesture = 'primary' | 'menu'

/** One pointer event as posted: what it was, which gesture it made (null: none), and on what. */
export type Sent = { seq: number; gesture: Gesture | null; target: Target; ev: PointerEv }

type Port = { post: (data: JsonValue) => void; every?: (ms: number, fn: () => void) => () => void }

const origin = Math.random().toString(36).slice(2, 10)
let seq = 0
let outbox: Sent[] = []
let rightDown = false // a right press reached this module and its release has not

function portOf(ctx: unknown): Port | null {
  const c = ctx as { post?: unknown; surface?: unknown } | null
  if (c && typeof c.post === 'function') return c as Port
  if (c && c.surface) return portOf(c.surface)
  return null
}

/** A Client's raw event (down/up) or an event already in this module's terms; null for moves and edges. */
export function normalize(ev: PointerEv | ClientPointerEvent): PointerEv | null {
  const t = ev.type === 'down' ? 'press' : ev.type === 'up' ? 'release' : ev.type
  if (t !== 'press' && t !== 'release' && t !== 'double') return null
  return { type: t, button: ev.button ?? 'left', shift: Boolean(ev.shift), ctrl: Boolean(ev.ctrl), alt: Boolean(ev.alt) }
}

/** The gesture a press makes: a left press (once or twice) its one action, a right press the menu; the rest none. */
export function classify(ev: PointerEv): Gesture | null {
  if (ev.type === 'double') return 'primary'
  if (ev.type !== 'press') return null
  if (ev.button === 'right') return 'menu'
  return ev.button === 'left' && !ev.shift && !ev.ctrl && !ev.alt ? 'primary' : null
}

export function targetKey(t: Target): string {
  return [t.kind, t.ref ?? '', t.cardId ?? '', (t.text ?? '').slice(0, 80)].join('|')
}

/** Every post carries what this module sent since the last frame, so a post that replaces another in the same frame
 *  (the engine delivers one per frame) loses no gesture; register.tsx drops the ones it has seen. */
function emit(port: Port, entry: Omit<Sent, 'seq'>): void {
  const mine = ++seq
  outbox = [...outbox, { ...entry, seq: mine }].slice(-8)
  port.post({ type: 'gesture', origin, gestures: outbox } as unknown as JsonValue)
  if (port.every) {
    const stop = port.every(120, () => {
      stop()
      outbox = outbox.filter(x => x.seq > mine)
    })
  }
}

/** A Client's other posts (a hover, a param) go through here, so they carry the gestures not yet delivered. */
export function send(ctx: unknown, data: Record<string, JsonValue>): void {
  const port = portOf(ctx)
  if (port) port.post({ ...data, origin, gestures: outbox } as unknown as JsonValue)
}

/** Called by a Client's pointer listener with the target under the pointer, on a press and on a release. `ctx` is the
 *  Client's surface (its `post`, and its `every` for the double-click window). */
export function onPointer(target: Target, ev: PointerEv | ClientPointerEvent, ctx: unknown): void {
  const port = portOf(ctx)
  const e = normalize(ev)
  if (!port || !e) return
  if (e.type === 'release') {
    // The press picks the menu's target. The menu's pane can reflow the transcript before the release, which then lands
    // on another target; only a right release whose press never reached this module opens the menu.
    const lost = e.button === 'right' && !rightDown
    if (e.button === 'right') rightDown = false
    emit(port, { gesture: lost ? 'menu' : null, target, ev: e })
    return
  }
  if (e.type === 'press' && e.button === 'right') rightDown = true
  emit(port, { gesture: classify(e), target, ev: e })
}

// ------------------------------------------------------------------------------------------------ what a target means

const CARD_REF = /^card:([A-Za-z0-9_-]+)/

/** The target's citation: a full `[[value|ref]]` in `ref`, `[[text|ref]]` for a mark or a row (its text is the value
 *  shown), or `[[ref]]` (a record's or a node's text is words about it, not a value). */
export function citationOf(t: Target): Citation | null {
  if (t.kind === 'card') return t.cardId ? { raw: `[[card:${t.cardId}]]`, ref: `card:${t.cardId}`, display: null } : null
  const ref = (t.ref ?? '').trim()
  if (!ref) return null
  if (ref.startsWith('[[')) return citations(ref)[0] ?? null
  const value = t.kind === 'mark' || t.kind === 'row' ? (t.text ?? '').trim() : ''
  return value && !/[|\[\]\n]/.test(value) ? { raw: `[[${value}|${ref}]]`, ref, display: value } : { raw: `[[${ref}]]`, ref, display: null }
}

export function cardOf(t: Target): string {
  return t.cardId || CARD_REF.exec(citationOf(t)?.ref ?? '')?.[1] || ''
}

/** What a double-click or "cite" puts into the prompt: the citation, or a sentence quoted. */
export function citeText(t: Target): string {
  const c = citationOf(t)
  if (c) return c.raw
  const s = (t.text ?? '').replace(/\s+/g, ' ').trim()
  return s ? `"${s.length > 300 ? `${s.slice(0, 299)}…` : s}"` : ''
}

/** The place a click opens: a citation's; a mark's, row's, record's or node's when it lies outside the cards. Plain
 *  words (a sentence, a reply's table row) open nothing: only what is drawn as a link opens a panel. */
export function placeOf(t: Target): Citation | null {
  if (t.kind === 'card' || t.kind === 'sentence' || (t.kind === 'row' && !t.ref)) return null
  const c = citationOf(t)
  if (!c) return null
  return t.kind === 'citation' || !CARD_REF.test(c.ref) ? c : null
}

export type Act = 'open' | 'thread' | 'verify' | 'script' | 'rerun'
export type MenuItem = { act: Act; label: string; hotkey: string }

/** The menu a right-click opens: every action the target has. */
export function menuItems(t: Target): MenuItem[] {
  const c = citationOf(t)
  const card = cardOf(t)
  const out: MenuItem[] = []
  if (placeOf(t)) out.push({ act: 'open', label: 'open', hotkey: 'o' })
  out.push({ act: 'thread', label: 'ask', hotkey: 'a' })
  if (c?.display && t.kind !== 'card' && t.kind !== 'sentence') out.push({ act: 'verify', label: 'verify', hotkey: 'v' })
  if (card && t.script) out.push({ act: 'script', label: 'open the script', hotkey: 's' }, { act: 'rerun', label: 'rerun', hotkey: 'r' })
  return out
}

/** `s` in at most `n` characters: whole when it fits, else cut at the last space that keeps half of it, then `…`. */
function shorten(s: string, n: number): string {
  if (s.length <= n) return s
  const room = Math.max(1, n - 1)
  const sp = s.lastIndexOf(' ', room)
  return `${(sp >= room / 2 ? s.slice(0, sp) : s.slice(0, room)).replace(/[\s,;:.]+$/, '')}…`
}

/** A short name for the target in at most `max` characters, as the menu and the mouse log show it: each citation by
 *  its label, never its ref; quoted words keep their closing quote when cut. */
export function targetLabel(t: Target, max = 48): string {
  const s = (t.text ?? '')
    .replace(/\[\[[^\[\]]+?\]\]/g, m => {
      const c = citations(m)[0]
      return c ? citeLabel(c) : m
    })
    .replace(/[`*_]+|^\s*(#+|[-*+]|\d+[.)])\s+/g, '')
    .replace(/\s+/g, ' ')
    .trim()
  const n = Math.max(8, max)
  const c = citationOf(t)
  switch (t.kind) {
    case 'card':
      return s ? `card "${shorten(s, n - 7)}"` : 'card'
    case 'sentence':
      return s ? `"${shorten(s, n - 2)}"` : 'sentence'
    case 'citation':
      return shorten(c ? citeLabel(c) : 'citation', n)
    default:
      return shorten(t.label || s || (c ? citeLabel(c) : t.kind), n)
  }
}

// ------------------------------------------------------------------------------------------------ the menu's target

/** Whether the open menu belongs to `t`. `menu` is the target the hooks module hands each Client in its `menu` prop
 *  while the menu is open (null once it closes). */
export function isMenuTarget(t: Target, menu: unknown): boolean {
  return typeof menu === 'object' && menu !== null && targetKey(menu as Target) === targetKey(t)
}

/** A paragraph's lines with the open menu's target shaded: its citation, its sentence (the words passageAt maps to
 *  it, and the spaces between them) or its table row. */
export function menuLines(lay: ParaLayout, raws: readonly string[], menu: unknown): Line[] {
  if (typeof menu !== 'object' || menu === null) return lay.lines
  const m = menu as Target
  const cells: { line: number; x0: number; x1: number }[] = []
  if (m.kind === 'citation') for (const s of lay.spans) if (raws[s.chip] === m.ref) cells.push(s)
  if (m.kind === 'row' && lay.rows) {
    lay.rows.forEach((r, y) => {
      if (r && isMenuTarget({ kind: 'row', text: r }, m)) cells.push({ line: y, x0: 0, x1: lineWidth(lay.lines[y] ?? []) })
    })
  }
  if (m.kind === 'sentence') {
    const byLine = new Map<number, { x0: number; x1: number }>()
    for (const w of lay.words) {
      if (!isMenuTarget({ kind: 'sentence', text: sentenceAt(lay.source, w.at) }, m)) continue
      const c = byLine.get(w.line)
      byLine.set(w.line, c ? { x0: Math.min(c.x0, w.x0), x1: Math.max(c.x1, w.x1) } : { x0: w.x0, x1: w.x1 })
    }
    for (const [line, c] of byLine) cells.push({ line, ...c })
  }
  return cells.length ? shade(lay.lines, cells, COLORS.menu) : lay.lines
}

files.hooks/threads.tsx:
// Side threads: a question about a card, a citation or the last answer, answered by a subagent the mod starts, so
// the exchange stays out of main's chat. register.tsx draws the pane (the exchange, its answers drawn like replies:
// links and cards); nothing goes back to main's prompt. A thread about a card may change the card in place.
//
// This file holds the prompts and the record; the engine is in register.tsx (the validator follows `$` only into
// functions of the hooks module's own file). The mod's other subagents (a fix round, a verification) start the same
// way: $.agent.spawn with the `fork` type, which inherits main's conversation, so it knows the cards and the reply;
// where a fork is refused, a general-purpose subagent given the guidance and the context. Each follow-up starts a new
// fork given the exchange so far (a resumed subagent's end would reach main as a task notification, and main would
// answer it in its chat).
import type { ChatFixItem, ChatThread, ChatThreadTurn } from '../types'
import { plainCites } from './cite'

const RULES = [
  'Answer here, briefly, the way thimble-cc-mod answers in the main conversation: numbers from code (run Python with Bash; a card with the helper when a chart or table answers it), every number and record cited as [[value|ref]].',
  'Do not change the corpus, and write only under .thimble-cc-mod/.',
].join(' ')

const CARD_REF = /^\[\[card:([A-Za-z0-9_-]+)\]\]$/

/** What a thread about a card may do besides answer: change the card where it stands in the reply. */
function cardRule(t: ChatThread): string {
  const id = CARD_REF.exec(t.ref)?.[1]
  return id
    ? [
        `The main reply cites values of this card, so change it in place only when every value it shows stays the same: another sort order, chart kind or wording of its labels. Then edit the script that made it and run it again with python3, keeping the card's question exactly as it is (the id comes from the question, so .thimble-cc-mod/cards/${id}.json is replaced and redrawn where it stands in the reply), and say in one sentence what changed.`,
        'For a view that changes its values (another grouping, cutoff, field or filter), make a new card with its own question and show it here, and leave this card as it is.',
      ].join(' ')
    : ''
}

function history(t: ChatThread): string {
  return t.turns
    .filter(x => x.state === 'done')
    .map(x => `Q: ${x.q}\nA: ${x.a}`)
    .join('\n\n')
}

export function forkPrompt(t: ChatThread, q: string): string {
  const past = history(t)
  return [
    'thimble-cc-mod side thread. The analyst reads this exchange in a pane beside the main conversation; the main conversation does not see it.',
    `It is about ${t.label}:`,
    t.context,
    '',
    ...(past ? ['', 'The exchange so far in this side thread:', past] : []),
    '',
    `The analyst asks: ${q}`,
    '',
    RULES,
    ...(cardRule(t) ? [cardRule(t)] : []),
  ].join('\n')
}

/** A prompt for a general-purpose subagent, which has neither main's conversation nor its guidance. */
export function withGuide(guide: string, prompt: string): string {
  return [guide, '', '---', prompt].join('\n')
}

export function freshPrompt(t: ChatThread, q: string, guide: string): string {
  return withGuide(guide, forkPrompt(t, q))
}

// How each subagent of the mod is named where Claude Code lists it and in its one dim row in main's chat; the names
// also tell the mod's rows from others.
export const MOD_AGENT = /(?:verification|side thread) · /

/** A fix round's name, by what it corrects. */
export function fixName(items: ChatFixItem[]): string {
  const what = [items.some(it => !it.card) && 'citations', items.some(it => it.card) && 'cards'].filter(Boolean).join(' and ')
  return `verification · correcting ${what || 'citations'}`
}

/** A verification script's name, by the value it recomputes. */
export function verifyName(value: string): string {
  return `verification · checking ${value}`
}

/** A side thread's name, by the first words of its question. */
export function threadName(q: string): string {
  return `side thread · ${firstWords(plainCites(q), 40)}`
}

function firstWords(s: string, n: number): string {
  const one = s.replace(/\s+/g, ' ').trim()
  if (one.length <= n) return one
  const cut = one.slice(0, n + 1)
  const sp = cut.lastIndexOf(' ')
  return `${(sp > n / 2 ? cut.slice(0, sp) : one.slice(0, n)).replace(/[\s,;:.]+$/, '')}…`
}

export function lastTurn(t: ChatThread, patch: Partial<ChatThreadTurn>): ChatThread {
  const turns = t.turns.slice()
  const i = turns.length - 1
  if (i >= 0) turns[i] = { ...turns[i]!, ...patch }
  return { ...t, turns }
}

/** A thread as the markdown file it is saved to. */
export function threadFile(t: ChatThread): string {
  return [`# Side thread: ${t.label}`, '', t.context, '', ...t.turns.flatMap(x => [`## ${x.q}`, '', x.a || `(${x.state})`, ''])].join('\n')
}

/** A thread as data, saved beside its markdown file so a later session can list and continue it. */
export function threadJson(t: ChatThread): string {
  return JSON.stringify({ ...t, agentId: '' }, null, 1)
}

/** A thread read back from its .json, or null when it is not one; a turn left running when its session ended is
 *  marked so. */
export function parseThread(raw: string): ChatThread | null {
  let v: unknown
  try {
    v = JSON.parse(raw)
  } catch {
    return null
  }
  const t = v as Partial<ChatThread> | null
  if (!t || typeof t.id !== 'string' || typeof t.label !== 'string' || !Array.isArray(t.turns)) return null
  const turns = t.turns
    .filter(x => x && typeof x.q === 'string')
    .map(x => (x.state === 'running' ? { ...x, state: 'error', a: x.a || '(the session ended before it answered)' } : x))
  return { id: t.id, label: t.label, ref: t.ref ?? '', context: t.context ?? '', agentId: '', engine: t.engine ?? '', turns, file: t.file ?? `.thimble-cc-mod/threads/${t.id}.md` }
}

files.hooks/card.tsx:
// A card as an interactive panel: a Client surface module, drawn on Claude Code's drawing thread (no `$`).
// The chart is text (block, braille and box-drawing characters), so the Client can redraw it per pointer move: the mark
// under the pointer is highlighted and its value shows at the right of the title. Presses on a mark, a record, a node or
// the card itself go to the gestures (onPointer), which decide what a click, a double-click or a right-click does. The
// one control row is the card's params: a choice runs the card's script again with it. As in para.tsx, a move off the
// card, a reflow or a hover on another card clears the hovered mark.
import type { ClientModule, ClientSurface } from 'claude-code'

import { cardLayout, cut, menuShade, width } from './draw'
import type { CardData, CardMeta, Item, Line, Seg } from './draw'
import { isMenuTarget, onPointer, send } from './gestures'
import type { Target } from './gestures'
import { COLORS, paintLine } from './paint'

type Props = { card: CardData; cols: number; plotRows?: number; debug?: boolean; meta?: CardMeta; pane?: boolean; menu?: Target | null }
/** `cols`: the width the hover was set at; after a reflow it is stale. */
type S = { hover: number; act: string; cols: number }

const PAD_X = 2 // border and padding on the left

// the card whose mark or param is hovered: one at a time
let hovered: ClientSurface<S> | null = null

function unhover(surface: ClientSurface<S>): void {
  const cur = surface.state
  if (hovered === surface) hovered = null
  if (!cur || (cur.hover === -1 && !cur.act)) return
  try {
    surface.setState({ ...cur, hover: -1, act: '' })
  } catch {
    // an instance that is gone has nothing to clear
  }
}

type Hot = { x0: number; x1: number; param: string; value: string }

/** The params row: each choice of each param, the current one inverted, and where each other choice is. */
function paramRow(card: CardData, hoverKey: string): { line: Line; hots: Hot[] } | null {
  const params = card.params ?? []
  if (!params.length) return null
  const line: Line = []
  const hots: Hot[] = []
  let x = 0
  const push = (seg: Seg, hot?: { param: string; value: string }) => {
    if (hot) hots.push({ x0: x, x1: x + width(seg.s), ...hot })
    line.push(seg)
    x += width(seg.s)
  }
  params.forEach((p, i) => {
    if (i) push({ s: '   ' })
    push({ s: `${p.name} `, fg: COLORS.dim })
    p.choices.forEach((c, j) => {
      if (j) push({ s: ' ' })
      const value = String(c)
      if (value === String(p.value)) push({ s: ` ${c} `, inv: true, b: true })
      else {
        const on = hoverKey === `${p.name}=${value}`
        push({ s: ` ${c} `, fg: on ? COLORS.accent : COLORS.dim, u: on }, { param: p.name, value })
      }
    })
  })
  return { line, hots }
}

function itemTarget(item: Item, card: CardData): Target {
  const t: Target = { kind: item.kind, ref: item.open, cardId: card.id }
  if (item.text) t.text = item.text
  // what the mark is called besides its value (a bar's label, a point's date), for the menu and a thread's header
  if (item.label && item.label !== item.text) t.label = item.value ? `${item.label}: ${item.value}` : item.label
  if (card.source?.script) t.script = card.source.script
  return t
}

function cardTarget(card: CardData): Target {
  const t: Target = { kind: 'card', ref: `card:${card.id}`, text: card.question, cardId: card.id }
  if (card.source?.script) t.script = card.source.script
  return t
}

const Card: ClientModule<Props, S> = (props, surface) => {
  const { Box, Text, Button } = surface.elements
  const cols = surface.columns || props.cols || 80
  const inner = Math.max(20, cols - 4)
  const fresh: S = { hover: -1, act: '', cols }
  const st = surface.state ?? fresh
  const stale = st.cols !== cols
  const hover = stale ? -1 : st.hover
  const card = props.card
  const meta = props.meta ?? {}

  // while a right-click's menu is open on the card its border is lit and its title shaded; on one of its marks, that
  // mark is drawn hovered and shaded
  const menuOnCard = isMenuTarget(cardTarget(card), props.menu)
  let lay = cardLayout(card, inner, hover, props.plotRows)
  const menuItem = props.menu ? lay.items.findIndex(it => isMenuTarget(itemTarget(it, card), props.menu)) : -1
  const shown = hover >= 0 ? hover : menuItem
  if (shown !== hover) lay = cardLayout(card, inner, shown, props.plotRows)
  const prow = paramRow(card, stale ? '' : st.act)
  const top = 2 + (prow ? 1 : 0) // border, title, params
  const rowsTall = surface.rows || Infinity

  const targetAt = (i: number): Target => (i >= 0 && lay.items[i] ? itemTarget(lay.items[i]!, card) : cardTarget(card))
  const select = (cur: S, i: number, act: string) => {
    if (i === cur.hover && act === cur.act && cur.cols === cols) return
    if (i < 0 && !act) return unhover(surface)
    if (hovered && hovered !== surface) unhover(hovered)
    hovered = surface
    surface.setState({ ...cur, hover: i, act, cols })
  }

  // set on every call, so the listener reads this call's layout and props
  surface.onPointer(ev => {
    const cur = surface.state ?? fresh
    const cx = ev.x - PAD_X
    const hot = prow && ev.y === 2 ? prow.hots.find(h => cx >= h.x0 && cx < h.x1) : undefined
    const i = hot ? -1 : lay.hit(cx, ev.y - top)
    const act = hot ? `${hot.param}=${hot.value}` : ''
    const plain = !ev.shift && !ev.ctrl && !ev.alt
    // the title is a Button (its press opens the card's thread, as the person's own click): a left click there is its
    if (ev.y === 1 && (ev.button ?? 'left') === 'left' && (ev.type === 'down' || ev.type === 'up')) return
    if (ev.type === 'down' || ev.type === 'up') {
      if (hot && plain && (ev.button ?? 'left') === 'left') {
        if (ev.type === 'down') send(surface, { type: 'param', card: card.id, name: hot.param, value: hot.value })
        return
      }
      onPointer(targetAt(i), ev, surface)
      if (ev.type === 'down') select(cur, i, act)
      return
    }
    if (ev.type !== 'move' || ev.x < 0 || ev.y < 0 || ev.x >= cols || ev.y >= rowsTall) {
      unhover(surface)
      return
    }
    select(cur, i, act)
  })
  // Keys only in the pane: a Client with a key listener keeps the keyboard after a click, so in the chat the analyst's
  // typing would go to the card instead of the prompt.
  if (props.pane) {
    surface.onKey(ev => {
      const cur = surface.state ?? fresh
      const n = lay.items.length
      const step = ev.key === 'up' || ev.key === 'left' ? -1 : ev.key === 'down' || ev.key === 'right' ? 1 : 0
      if (step && n) {
        surface.setState({ ...cur, cols, hover: Math.min(n - 1, Math.max(0, (cur.hover < 0 ? (step > 0 ? -1 : n) : cur.hover) + step)) })
        return
      }
      if ((ev.key === 'return' || ev.key === 'enter') && cur.hover >= 0) {
        onPointer(targetAt(cur.hover), { button: 'left', shift: Boolean(ev.shift), ctrl: Boolean(ev.ctrl), alt: false, type: 'press' }, surface)
      }
    })
  }
  if (surface.state === undefined) surface.setState(st)

  // the title, and at its right the value under the pointer, or what the mod is doing to the card
  const item = shown >= 0 ? lay.items[shown] : undefined
  const right: Seg | null = item
    ? { s: cut(item.value ? `${item.label}: ${item.value}` : item.label, Math.max(12, Math.floor(inner * 0.6))), b: true, fg: COLORS.accent }
    : meta.busy
      ? { s: cut(meta.busy, 40), fg: COLORS.dim }
      : meta.error
        ? { s: cut(meta.error, Math.max(12, Math.floor(inner * 0.6))), fg: COLORS.problem }
        : null
  const rw = right ? width(right.s) + 2 : 0
  const title = cut(card.question, Math.max(8, inner - rw))
  // the title: a Button, lit and underlined under the pointer, whose press register.tsx answers (ui.press) with a side
  // thread about the card; at its right the value under the pointer
  const tail: Line = right ? [{ s: ' '.repeat(Math.max(2, inner - width(title) - width(right.s))) }, right] : []
  const titleButton = Button({
    key: `card-title:${card.id}`,
    label: title,
    plain: true,
    hover: { scope: `card-title-${card.id}`, color: COLORS.accent, underline: true },
    onPress: () => undefined,
  })
  const rows = [Box({ flexDirection: 'row', ...(menuOnCard ? { backgroundColor: COLORS.menu } : {}), children: [titleButton, paintLine(Text, tail)] })]
  if (prow) rows.push(paintLine(Text, prow.line))
  rows.push(...(menuItem >= 0 && shown === menuItem ? menuShade(lay, menuItem) : lay.lines).map(l => paintLine(Text, l)))
  return Box({
    flexDirection: 'column',
    borderStyle: 'round',
    borderColor: meta.error ? COLORS.problem : menuOnCard || menuItem >= 0 ? COLORS.accent : COLORS.rule,
    paddingX: 1,
    width: cols,
    children: rows,
  })
}

export default Card

files.hooks/para.tsx:
// A paragraph (or a table) of a reply that holds citations: a Client surface module, drawn on Claude Code's drawing
// thread (no `$`). It wraps the block to its region, draws each citation as a link (cite.ts), animates the spinner of
// a citation a fix round or a verification is working on, shows the hovered citation's ref beside it, and hands each
// press to gestures.tsx with what is under the pointer: a citation, a table row, or the sentence of the word there.
// While the right-click menu is open on one of its passages, that passage is shaded.
//
// A Client holds the pointer from press to release, so the terminal cannot select its text: the paragraph selects it
// itself. A drag lights the cells it covers and, on release, the text goes to the clipboard (register.tsx copies it);
// a press and release on one cell is a click, acted on at the release. Beside a selection, an "ask about this" Button
// (its press is the person's own, so register.tsx opens a side thread about the selected text at any width).
//
// A hovered citation is lit and tipped only while the pointer moves over it: a press, a move off the region, a
// reflow of the transcript (a pane opening beside it) or a hover in another paragraph clears it, since the engine does
// not always report the pointer leaving.
import type { ClientModule, ClientSurface, RenderElement } from 'claude-code'

import { blockLayout, passageAt } from './cite'
import type { ChipView } from './cite'
import { lineWidth, shade, width } from './draw'
import { menuLines, onPointer, send } from './gestures'
import type { Target } from './gestures'
import type { Run, TableRuns } from './lib'
import { COLORS, paintLine } from './paint'

type Props = {
  cols: number
  block: { prefix: string; heading: number; quote: boolean; runs: Run[]; table?: TableRuns }
  chips: ChipView[]
  /** each citation's claim key (cite.ts claimKey) */
  ids: string[]
  raws: string[]
  menu?: Target | null
}
/** A selection, from the cell pressed to the cell the drag is on (either order). */
type Sel = { y0: number; x0: number; y1: number; x1: number }
/** `cols`: the width the hover and the selection were set at; after a reflow they are stale. */
type S = { hover: number; frame: number; cols: number; sel?: Sel | null }

// a left press not yet released, per instance: where, on what, and whether the pointer has moved off its cell
const pressed = new WeakMap<object, { y: number; x: number; target: Target | null; moved: boolean }>()
// where each instance drew its "ask about this" Button, so a press on it is the Button's, not a new selection
const askAt = new WeakMap<object, { line: number; x0: number; x1: number }>()
const ASK = ' ask '

/** The selection's cells, line by line, in reading order. */
function selCells(sel: Sel, lines: number): { line: number; x0: number; x1: number }[] {
  const [a, b] = sel.y0 < sel.y1 || (sel.y0 === sel.y1 && sel.x0 <= sel.x1) ? [{ y: sel.y0, x: sel.x0 }, { y: sel.y1, x: sel.x1 }] : [{ y: sel.y1, x: sel.x1 }, { y: sel.y0, x: sel.x0 }]
  const out: { line: number; x0: number; x1: number }[] = []
  for (let y = Math.max(0, a.y); y <= Math.min(lines - 1, b.y); y++) out.push({ line: y, x0: y === a.y ? Math.max(0, a.x) : 0, x1: y === b.y ? b.x + 1 : 9999 })
  return out
}

/** The text a selection covers: wrapped lines joined by a space, a table's rows by a newline. */
export function selectedText(lines: readonly { s: string }[][], sel: Sel, table: boolean): string {
  return selCells(sel, lines.length)
    .map(c => Array.from((lines[c.line] ?? []).map(g => g.s).join('')).slice(c.x0, c.x1).join('').trimEnd())
    .join(table ? '\n' : ' ')
    .trim()
}

const TIP_BG = '#1f2428'
const TIP_FG = '#e6edf3'

// each instance's latest props, for its spinner tick
const latest = new WeakMap<object, Props>()
// the instance whose citation is hovered: one at a time
let hovered: ClientSurface<S> | null = null

function unhover(surface: ClientSurface<S>): void {
  const cur = surface.state
  if (hovered === surface) hovered = null
  if (!cur || cur.hover === -1) return
  try {
    surface.setState({ ...cur, hover: -1 })
    send(surface, { type: 'hover', id: '' })
  } catch {
    // an instance that is gone has nothing to clear
  }
}

const Para: ClientModule<Props, S> = (props, surface) => {
  const { Box, Text, Button } = surface.elements
  const cols = surface.columns || props.cols || 80
  const st = surface.state ?? { hover: -1, frame: 0, cols }
  const hover = st.cols === cols ? st.hover : -1
  const lay = blockLayout(props.block, props.chips, cols, hover, st.frame)
  latest.set(surface, props)

  // set on every call, so the listener reads this call's layout
  surface.onPointer(ev => {
    const cur = surface.state ?? { hover: -1, frame: 0, cols }
    const k = lay.spans.find(s => s.line === ev.y && ev.x >= s.x0 && ev.x < s.x1)?.chip ?? -1
    const targetAt = (x: number, y: number): Target | null => {
      const c = lay.spans.find(s => s.line === y && x >= s.x0 && x < s.x1)?.chip ?? -1
      return c >= 0 ? { kind: 'citation', ref: props.raws[c] ?? '', text: props.chips[c]?.label ?? '', claim: props.ids[c] ?? '' } : passageAt(lay, x, y)
    }
    const mods = { shift: Boolean(ev.shift), ctrl: Boolean(ev.ctrl), alt: Boolean(ev.alt) }
    // a left press starts a click or a selection; the release tells which
    const ask = askAt.get(surface)
    if (ask && ev.y === ask.line && ev.x >= ask.x0 && ev.x < ask.x1 && ev.button === 'left' && (ev.type === 'down' || ev.type === 'up')) return
    if (ev.type === 'down' && ev.button === 'left') {
      unhover(surface)
      pressed.set(surface, { y: ev.y, x: ev.x, target: targetAt(ev.x, ev.y), moved: false })
      if (cur.sel) surface.setState({ ...(surface.state ?? cur), sel: null })
      return
    }
    if (ev.type === 'move' && ev.button === 'left') {
      const p = pressed.get(surface)
      if (!p) return
      if (ev.y !== p.y || ev.x !== p.x) p.moved = true
      if (p.moved) surface.setState({ ...(surface.state ?? cur), cols, hover: -1, sel: { y0: p.y, x0: p.x, y1: Math.max(0, Math.min(lay.lines.length - 1, ev.y)), x1: Math.max(0, ev.x) } })
      return
    }
    if (ev.type === 'up' && ev.button === 'left') {
      const p = pressed.get(surface)
      pressed.delete(surface)
      if (!p) return
      if (!p.moved) {
        if (p.target) onPointer(p.target, { button: 'left', ...mods, type: 'press' }, surface)
        return
      }
      const sel = surface.state?.sel
      const text = sel ? selectedText(lay.lines, sel, Boolean(props.block.table)) : ''
      // one post: a later one in the same frame would replace it; a redraw shows "ask about this" by the selection
      if (text) send(surface, { type: 'copy', text })
      surface.setState({ ...(surface.state ?? cur), sel: text ? sel : null })
      return
    }
    if ((ev.type === 'down' || ev.type === 'up') && ev.button) {
      const target = targetAt(ev.x, ev.y)
      if (target) onPointer(target, { button: ev.button, ...mods, type: ev.type === 'down' ? 'press' : 'release' }, surface)
      if (ev.type === 'down') unhover(surface)
      return
    }
    if (ev.type !== 'move' || ev.x < 0 || ev.y < 0 || ev.x >= cols || ev.y >= lay.lines.length) {
      unhover(surface)
      return
    }
    if (k === cur.hover && cur.cols === cols) return
    if (k < 0) {
      unhover(surface)
      return
    }
    if (hovered && hovered !== surface) unhover(hovered)
    hovered = surface
    surface.setState({ ...cur, hover: k, cols })
    // the band shows the hovered citation's ref and status, whatever room the paragraph has for a tip
    send(surface, { type: 'hover', id: props.ids[k] ?? '' })
  })
  if (surface.state === undefined) {
    surface.setState(st)
    surface.every(150, () => {
      const p = latest.get(surface)
      const cur = surface.state
      if (p && cur && p.chips.some(c => c.spin)) surface.setState({ ...cur, frame: cur.frame + 1 })
    })
  }

  const sel = st.cols === cols ? st.sel : null
  const lit = sel ? shade(menuLines(lay, props.raws, props.menu), selCells(sel, lay.lines.length), COLORS.highlight) : menuLines(lay, props.raws, props.menu)
  const rows: RenderElement[] = lit.map(l => paintLine(Text, l))
  const span = hover >= 0 ? lay.spans.find(s => s.chip === hover) : undefined
  const tip = hover >= 0 ? props.chips[hover]?.tip : undefined
  // a tip over the line above the citation, or below it on a first line, or on a one-line paragraph after its text
  // (an absolute Box is clipped to the region, which is one row tall then)
  if (span && tip) {
    const room = Math.max(10, cols - 3)
    let text = width(tip) > room ? `${tip.slice(0, room - 1)}…` : tip
    let top = span.line > 0 ? span.line - 1 : lay.lines.length > 1 ? span.line + 1 : 0
    let left = Math.max(0, Math.min(span.x0, cols - width(text) - 2))
    if (lay.lines.length === 1) {
      const end = lineWidth(lay.lines[0]!) + 2
      const free = cols - end - 2
      text = free >= 12 ? (width(tip) > free ? `${tip.slice(0, free - 1)}…` : tip) : ''
      left = end
      top = 0
    }
    if (text) rows.push(Box({ position: 'absolute', top, left, children: Text({ backgroundColor: TIP_BG, color: TIP_FG, children: ` ${text} ` }) }))
  }
  // a released selection: "ask about this" on the line below its end, or at the right of its last line
  askAt.delete(surface)
  if (sel && !pressed.get(surface)) {
    const cells = selCells(sel, lay.lines.length)
    const end = cells.at(-1)
    if (end) {
      const w = width(ASK)
      const below = end.line + 1 < lay.lines.length
      const line = below ? end.line + 1 : end.line
      const x0 = Math.max(0, below ? Math.min(Math.min(end.x1, lineWidth(lay.lines[end.line]!)) - 1, cols - w) : cols - w)
      askAt.set(surface, { line, x0, x1: x0 + w })
      rows.push(Box({ position: 'absolute', top: line, left: x0, children: Button({ key: 'sel-ask', label: ASK, plain: true, variant: 'primary', onPress: () => undefined }) }))
    }
  }
  return Box({ flexDirection: 'column', children: rows })
}

export default Para

